/** The reference files of an ATH sub-variant, or null for any other strategy. */
export function athReference(id: string | undefined): BtstReference | null {
  return id && Object.prototype.hasOwnProperty.call(ATH_REFERENCES, id) ? ATH_REFERENCES[id] : null;
}

export const ATH_VARIANT_IDS = Object.keys(ATH_REFERENCES);

/** Sub-variants added from the team's "AFL ATH checking" folder (shown with a green name). */
export const ATH_CHECKED_IDS: string[] = ["ytath_chk_5pct_to_40pct_scanner", "ytath_chk_pctswing_turnover_running_buy", "ytath_chk_all_st_variations_all_ranking", "ytath_chk_19pct_swing_sl_probability"];

/** Every file path the references point to, relative to the ATH folder (used to check they exist). */
export function athReferencedPaths(): string[] {
  const out = new Set<string>();
  for (const [id, r] of Object.entries(ATH_REFERENCES)) {
    if (!ATH_CHECKED_IDS.includes(id)) out.add(r.afl);
    for (const f of r.tradesheets) out.add(f.file);
    if (r.summary) out.add(r.summary.file);
  }
  return [...out];
}
